import heapq

def dijkstra(graph, source):
    dist = {n: float('inf') for n in graph}
    prev = {n: None for n in graph}
    dist[source] = 0
    heap = [(0, source)]
    visited = set()
    while heap:
        d_u, u = heapq.heappop(heap)
        if u in visited: continue
        visited.add(u)
        for v, w in graph[u]:
            if v not in visited and d_u + w &lt; dist[v]:
                dist[v] = d_u + w
                prev[v] = u
                heapq.heappush(heap, (dist[v], v))
    return dist, prev
